css:
.mz *,.mz *::before,.mz *::after{box-sizing: border-box; margin: 0; padding: 0;}
.mz .unir-tabla{display: grid; grid-template-columns: 130px 1fr 130px; gap: 4px; margin-bottom: 4px; align-items: center;}
.mz .unir-izq{font-size: 14px; font-weight: 700; text-align: center; border: 1.5px solid var(--bosque); border-radius: 6px; padding: 6px 0;}
.mz .unir-der{font-size: 13.5px; font-weight: 600; text-align: center; border: 1.5px solid var(--bosque); border-radius: 6px; padding: 6px 0;}
.mz .frase-fila{display: grid; grid-template-columns: 1fr 90px; gap: 10px; padding: 5px 10px; border: 1.2px solid var(--bosque); border-radius: 6px; margin-bottom: 4px; align-items: center;}
.mz .frase-texto{font-size: 14px; font-weight: 600;}
.mz .frase-texto .hueco{display: inline-block; min-width: 70px; border-bottom: 1.5px solid var(--bosque); margin: 0 3px;}
.mz .frase-pista{font-size: 11px; font-family: sans-serif; color: #444; text-align: right;}
.mz .orden-fila{display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 10px; margin-bottom: 8px;}
.mz .orden-caja{border: 1.5px solid var(--bosque); border-radius: 6px; padding: 7px 6px; min-height: 50px; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 5px;}
.mz .orden-nombre{font-size: 14px; font-weight: 700; text-align: center;}
.mz .orden-linea{font-family: sans-serif; font-size: 16px; font-weight: 700; letter-spacing: 1px;}
.mz .orden-hueco{width: 26px; height: 26px; border: 1.5px solid var(--bosque); border-radius: 5px;}
